package com.example.contacts.data;
import android.content.Context;import android.database.Cursor;import android.net.Uri;import android.provider.ContactsContract;
public final class ContactsRepository{
 private ContactsRepository(){}
 public static Cursor phones(Context c){String[] p={ContactsContract.CommonDataKinds.Phone._ID,ContactsContract.CommonDataKinds.Phone.CONTACT_ID,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER,ContactsContract.CommonDataKinds.Phone.TYPE,ContactsContract.CommonDataKinds.Phone.PHOTO_THUMBNAIL_URI,ContactsContract.CommonDataKinds.Phone.STARRED};return c.getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,p,null,null,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME+" COLLATE LOCALIZED ASC");}
 public static String phoneType(int t){switch(t){case ContactsContract.CommonDataKinds.Phone.TYPE_MOBILE:return "נייד";case ContactsContract.CommonDataKinds.Phone.TYPE_HOME:return "בית";case ContactsContract.CommonDataKinds.Phone.TYPE_WORK:return "עבודה";case ContactsContract.CommonDataKinds.Phone.TYPE_MAIN:return "ראשי";case ContactsContract.CommonDataKinds.Phone.TYPE_FAX_HOME:return "פקס בית";case ContactsContract.CommonDataKinds.Phone.TYPE_FAX_WORK:return "פקס עבודה";default:return "טלפון";}}
 public static String lookupName(Context c,String n){Cursor x=null;try{Uri u=Uri.withAppendedPath(ContactsContract.PhoneLookup.CONTENT_FILTER_URI,Uri.encode(n));x=c.getContentResolver().query(u,new String[]{ContactsContract.PhoneLookup.DISPLAY_NAME},null,null,null);if(x!=null&&x.moveToFirst())return x.getString(0);}finally{if(x!=null)x.close();}return "";}
 public static long rawId(Context c,long id){Cursor x=null;try{x=c.getContentResolver().query(ContactsContract.RawContacts.CONTENT_URI,new String[]{ContactsContract.RawContacts._ID},ContactsContract.RawContacts.CONTACT_ID+"=?",new String[]{String.valueOf(id)},null);if(x!=null&&x.moveToFirst())return x.getLong(0);}finally{if(x!=null)x.close();}return -1;}
}